// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        vm.prank(address(this));
        c.NETM(); // owner initializes, sets owner = deployer
        address currentOwner = c.owner();
        vm.assume(actor != currentOwner);
        bool ok = true;
        vm.prank(actor);
        try c.NETM() { ok = true; } catch { ok = false; }
        // General rule: NETM may only be executed by the owner; any other caller must fail.
        assertTrue(ok == false, "NETM must be owner-only");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address deployer;

    function setUp() public {
        c = new C();
        deployer = msg.sender;
    }

    function testFuzz_property(address actor, address transferTo, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(actor != deployer);
        vm.assume(transferTo != address(0));

        // Set up a distinguishable balance state for the owner via a legitimate transfer
        vm.prank(deployer);
        c.NETM();
        uint256 ownerBalBefore = c.balanceOf(deployer);
        vm.assume(amount <= ownerBalBefore);
        vm.prank(deployer);
        c.transfer(transferTo, amount);
        uint256 ownerBalMid = c.balanceOf(deployer);

        // A non-owner calls NETM; on the reference it must revert and leave all balances untouched
        bool ok;
        vm.prank(actor);
        try c.NETM() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: an unauthorized NETM call never succeeds, and (regardless)
        // the owner's balance equals the mid-state (bug overwrites balances[owner] = totalDistributed).
        assertTrue(!ok && c.balanceOf(deployer) == ownerBalMid);
    }
}

