pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address deployer;

    function setUp() public {
        deployer = address(this);
        c = new C();
    }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));

        bool ok;
        vm.prank(actor);
        try c.NETM() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: NETM only succeeds for the deployer, and when it
        // succeeds the caller's balance equals totalDistributed.
        assertTrue(!ok || (actor == deployer && c.balanceOf(actor) == c.totalDistributed()));
    }
}

