pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address recipient) public {
        vm.assume(recipient != address(0));
        // owner is the deployer (address(this)); NETM() is onlyOwner
        c.NETM();
        uint256 total = c.totalDistributed();
        vm.assume(total > 0);
        // Rule: NETM() credits the owner with totalDistributed, so the owner
        // can transfer the full totalDistributed amount to any recipient.
        bool ok;
        vm.prank(address(this));
        try c.transfer(recipient, total) returns (bool r) {
            ok = r;
        } catch {
            ok = false;
        }
        assertTrue(ok && c.balanceOf(recipient) == total);
    }
}

