pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 seed) public {
        // NETM() is onlyOwner; owner is fixed at deployment (this test contract).
        // Whoever calls, the rule: if NETM() succeeds, owner's balance must equal totalDistributed.
        address ow = c.owner();
        vm.prank(ow);
        bool ok;
        try c.NETM() { ok = true; } catch { ok = false; }
        if (ok) {
            assertEq(c.balanceOf(ow), c.totalDistributed());
        } else {
            assertTrue(true);
        }
    }
}

