pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        vm.assume(!c.blacklist(actor));

        // trigger a distribution so totalDistributed != totalRemaining
        uint256 amt = 1 wei;
        vm.deal(actor, amt);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: amt}("");
        assertTrue(ok);

        // owner (the deployer, this contract) re-initializes via NETM
        vm.prank(address(this));
        c.NETM();

        // general rule: after NETM, the owner's balance equals totalDistributed
        assertTrue(c.balanceOf(address(this)) == c.totalDistributed());
    }
}

